use xiom.io;
enum Suit { Hearts, Spades, }
enum Rank { Ace, King, }
type Card = { suit: Suit; rank: Rank; }

fn create_deck() -> Vec[Card] {
  var deck: Vec[Card] = Vec[Card].new();
  deck.push(Card{ suit: Suit.Hearts, rank: Rank.Ace });
  deck.push(Card{ suit: Suit.Hearts, rank: Rank.King });
  deck.push(Card{ suit: Suit.Spades, rank: Rank.Ace });
  deck.push(Card{ suit: Suit.Spades, rank: Rank.King });
  deck
}

fn deal_card(deck: &mut Vec[Card]) -> Option[Card] {
  if deck.len() == 0 { return None; };
  let last = deck.len() - 1;
  let card = deck[last];
  deck.remove(last);
  Some(card)
}

fn main() -> Int {
  var deck = create_deck();
  io.println(deck.len().to_str());
  let card = deal_card(&mut deck);
  io.println(deck.len().to_str());
  return 0;
}
